import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, vec2, vec3, float, uniform, mix, MeshStandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-divider';
  group.position.set(-1.25, -0.2, 0);

  const width = 3.0;
  const height = 0.1875;

  const geometry = new THREE.PlaneGeometry(width, height, 64, 64);

  const colorMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const parallaxOffset = uniform(vec2(0, 0));
  const displacementStrength = uniform(float(0.015));

  const material = new MeshStandardNodeMaterial();
  material.metalness = 0.5;
  material.roughness = 0.55;

  const baseUv = uv();
  const depthSample = texture(depthMap, baseUv).r;
  const parallaxUv = baseUv.add(parallaxOffset.mul(depthSample));

  material.colorNode = texture(colorMap, parallaxUv);

  const displaced = positionLocal.add(
    vec3(0, 0, depthSample.sub(0.5).mul(displacementStrength))
  );
  material.positionNode = displaced;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'divider-plane';
  group.add(mesh);

  // Center jewel — accent-colored sphere as focal point
  const jewelGeo = new THREE.SphereGeometry(0.045, 24, 24);
  const jewelMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#ff2a38'),
    metalness: 0.55,
    roughness: 0.35,
    clearcoat: 0.25,
    clearcoatRoughness: 0.2,
  });
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.03);
  jewel.name = 'jewel';
  group.add(jewel);

  // Baseline for rise-in hover animation
  const baseY = group.position.y;
  let hoverTween = null;
  let pressTween = null;

  function onHover() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onHoverEnd() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onClick() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-features.select', { source: group.name });
    }
  }

  function onPointerMove(event) {
    if (event && typeof event.x === 'number' && typeof event.y === 'number') {
      parallaxOffset.value.set(event.x * 0.01, event.y * 0.01);
    }
  }

  group.userData.handlers = {
    hover: onHover,
    hoverEnd: onHoverEnd,
    click: onClick,
    pointerMove: onPointerMove,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    colorMap.dispose();
    depthMap.dispose();
  };

  return group;
}
